from z3 import *
P=[]; C=[]
for line in open('/app/pairs.txt'):
 a,b=map(int,line.split());P.append(a);C.append(b)

def f(v):
    x=[Extract(8*i+7,8*i,v) for i in range(4)]
    def g(a,b,c):
        return RotateLeft(a+b+BitVecVal(c,8),2)
    y=[None]*4
    y[2]=g(x[3]^x[2],x[1]^x[0],1)
    y[3]=g(x[3],y[2],0)
    y[1]=g(x[1]^x[0],y[2],0)
    y[0]=g(x[0],y[1],1)
    return Concat(y[3],y[2],y[1],y[0])
def expand(s):
    k=ZeroExt(12,s)
    return k ^ (k << 16) ^ (k * 12345)
def enc(p,ks):
    l=Extract(63,32,BitVecVal(p,64)); r=Extract(31,0,BitVecVal(p,64))
    r=r^l
